        # pre1 and pre2 are lists of identifier strings
        # A version without pre-release sorts after one with pre-release
        if not pre1 and not pre2:
            return 0
        if not pre1:
            return 1  # no prerelease sorts after prerelease
        if not pre2:
            return -1  # prerelease sorts before no prerelease

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

