                # Both numeric, compare numerically
                result = int(id1) - int(id2)
                if result != 0:
                    return result
            elif is_num1:
                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare lexically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)

        # Create a sort key: (major, minor, patch, prerelease_sort_key)
        # For prerelease: if empty, it sorts after non-empty, so use (1,) for no prerelease
        # and (0, ...) for with prerelease
        if not prerelease_identifiers:
            prerelease_key = (1,)
        else:
            # Convert each identifier to a comparable form
            converted = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    # Numeric: (0, numeric_value) - 0 sorts before non-numeric
                    converted.append((0, int(identifier)))
                else:
                    # Non-numeric: (1, string_value)
                    converted.append((1, identifier))
            prerelease_key = (0, tuple(converted))

        return (major, minor, patch, prerelease_key)

    # Sort using stable sort with the key function
    return sorted(versions, key=sort_key)

